from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Any, Dict, List, Optional

from rasa.dialogue_understanding.stack.frames.dialogue_stack_frame import (
    DialogueStackFrame,
)
from rasa.shared.core.flows import Flow, FlowsList, FlowStep
from rasa.shared.core.flows.steps.constants import START_STEP
from rasa.shared.exceptions import RasaException
from rasa.shared.utils.dict_access import require_keys


class InvalidFlowStackFrameType(RasaException):
    """Raised if the stack frame type is invalid."""

    def __init__(self, frame_type: Optional[str]) -> None:
        """Creates a `InvalidFlowStackFrameType`.

        Args:
            frame_type: The invalid stack frame type.
        """
        super().__init__(f"Invalid stack frame type '{frame_type}'.")


class FlowStackFrameType(str, Enum):
    INTERRUPT = "interrupt"
    """The frame is an interrupt frame.

    This means that the previous flow was interrupted by this flow. An
    interrupt should be used for frames that span multiple turns and
    where we expect the user needing help to get back to the previous
    flow."""
    LINK = "link"
    """The frame is a link frame.

    This means that the previous flow linked to this flow."""

    CALL = "call"
    """The frame is a flow that is called from another flow."""

    REGULAR = "regular"
    """The frame is a regular frame.

    In all other cases, this is the case."""

    @staticmethod
    def from_str(typ: Optional[str]) -> "FlowStackFrameType":
        """Creates a `FlowStackFrameType` from a string.

        Args:
            typ: The string to create the `FlowStackFrameType` from.

        Returns:
        The created `FlowStackFrameType`.
        """
        if typ is None:
            return FlowStackFrameType.REGULAR
        elif typ == FlowStackFrameType.INTERRUPT.value:
            return FlowStackFrameType.INTERRUPT
        elif typ == FlowStackFrameType.CALL.value:
            return FlowStackFrameType.CALL
        elif typ == FlowStackFrameType.LINK.value:
            return FlowStackFrameType.LINK
        elif typ == FlowStackFrameType.REGULAR.value:
            return FlowStackFrameType.REGULAR
        else:
            raise InvalidFlowStackFrameType(typ)


class InvalidFlowIdException(Exception):
    """Raised if the flow ID is invalid."""

    def __init__(self, flow_id: str) -> None:
        """Creates a `InvalidFlowIdException`.

        Args:
            flow_id: The invalid flow ID.
        """
        super().__init__(f"Invalid flow ID '{flow_id}'.")


class InvalidAgentState(RasaException):
    """Raised if the agent state is invalid."""

    def __init__(self, invalid_state: str) -> None:
        """Creates a `InvalidAgentState`.

        Args:
            invalid_state: The invalid agent state.
        """
        super().__init__(f"Invalid agent state '{invalid_state}'.")


@dataclass
class BaseFlowStackFrame(DialogueStackFrame):
    flow_id: str = ""  # needed to avoid "default arg before non-default" error
    """The ID of the current flow."""
    step_id: str = START_STEP
    """The ID of the current step."""

    def flow(self, all_flows: FlowsList) -> Flow:
        """Returns the current flow.

        Args:
            all_flows: All flows in the assistant.

        Returns:
        The current flow.
        """
        flow = all_flows.flow_by_id(self.flow_id)
        if not flow:
            # we shouldn't ever end up with a frame that belongs to a non
            # existing flow, but if we do, we should raise an error
            raise InvalidFlowIdException(self.flow_id)
        return flow

    def step(self, all_flows: FlowsList) -> Optional[FlowStep]:
        """Returns the current flow step, or ``None`` if the frame is stale.

        Returns ``None`` when the step ID no longer resolves in the current
        model — typically because flows were modified or removed across an
        upgrade and historical events rehydrated a frame referencing the old
        step. ``MessageProcessor._purge_stale_user_flow_frames`` is the
        primary cleanup mechanism; this return value is defense-in-depth so
        every call site fails closed instead of crashing the conversation.

        Args:
            all_flows: All flows in the assistant.

        Returns:
            The current flow step, or ``None`` if it no longer exists.
        """
        flow = self.flow(all_flows)

        # in 3.11.4 we added the flow_id as a prefix to the step_id; this
        # causes issues when loading old dialogues as the prefix is missing
        # (see https://rasahq.atlassian.net/jira/software/c/projects/ENG/boards/43?selectedIssue=ENG-1939)
        # TODO: remove this in 4.0.0
        alternative_step_id = f"{self.flow_id}_{self.step_id}"
        return flow.step_by_id(self.step_id) or flow.step_by_id(alternative_step_id)


@dataclass
class UserFlowStackFrame(BaseFlowStackFrame):
    frame_type: FlowStackFrameType = FlowStackFrameType.REGULAR
    """The type of the frame. Defaults to `StackFrameType.REGULAR`."""
    suspended_agent_frames: Optional[List[Dict[str, Any]]] = None
    """Agent stack frames (as dicts) to restore when reaching that agent's step.

    Used when rewinding the stack (e.g. slot correction or agent restart) so
    interrupted agents can be resumed. Old trackers may have no key; treat as None.
    """

    @classmethod
    def type(cls) -> str:
        """Returns the type of the frame."""
        return "flow"

    def as_dict(self) -> Dict[str, Any]:
        """Serialize to dict; omit suspended_agent_frames when None to avoid bloat."""
        data = super().as_dict()
        if data.get("suspended_agent_frames") is None:
            data.pop("suspended_agent_frames", None)
        return data

    @staticmethod
    def from_dict(data: Dict[str, Any]) -> UserFlowStackFrame:
        """Creates a `DialogueStackFrame` from a dictionary.

        Args:
            data: The dictionary to create the `DialogueStackFrame` from.

        Returns:
            The created `DialogueStackFrame`.
        """
        suspended = data.get("suspended_agent_frames")
        if suspended is not None and not isinstance(suspended, list):
            suspended = None
        require_keys(
            data,
            "frame_id",
            "flow_id",
            "step_id",
            context="User flow stack frame",
        )
        return UserFlowStackFrame(
            frame_id=data["frame_id"],
            flow_id=data["flow_id"],
            step_id=data["step_id"],
            frame_type=FlowStackFrameType.from_str(data.get("frame_type")),
            suspended_agent_frames=suspended,
        )


class AgentState(str, Enum):
    TERMINAL = "terminal"
    INTERRUPTED = "interrupted"
    WAITING_FOR_INPUT = "waiting_for_input"
    # Transient state set by `resume_flow()` (and by
    # `_restore_suspended_agent_frame_if_any` on the correction/restart path) when
    # an interrupted agent is reordered back to the top of the stack. Signals
    # `run_agent` to re-invoke the agent with `resumed_after_interruption=True`;
    # cleared in the same cycle to WAITING_FOR_INPUT (agent yielded) or by
    # removing the frame (agent completed)
    RESUMING = "resuming"
    WAITING_FOR_INPUT_FROM_PUSH_NOTIFICATION = (
        "waiting_for_input_from_push_notification"
    )
    COMPLETED = "completed"
    PROCESSING = "processing"

    @staticmethod
    def from_str(state: Optional[str]) -> AgentState:
        if state == AgentState.WAITING_FOR_INPUT.value:
            return AgentState.WAITING_FOR_INPUT
        if state == AgentState.WAITING_FOR_INPUT_FROM_PUSH_NOTIFICATION.value:
            return AgentState.WAITING_FOR_INPUT_FROM_PUSH_NOTIFICATION
        elif state == AgentState.INTERRUPTED.value:
            return AgentState.INTERRUPTED
        elif state == AgentState.RESUMING.value:
            return AgentState.RESUMING
        elif state == AgentState.COMPLETED.value:
            return AgentState.COMPLETED
        elif state == AgentState.PROCESSING.value:
            return AgentState.PROCESSING
        elif state == AgentState.TERMINAL.value:
            return AgentState.TERMINAL
        else:
            raise InvalidAgentState(state)


@dataclass
class AgentStackFrame(BaseFlowStackFrame):
    agent_id: str = ""
    agent_task_id: str = ""
    context_id: str = ""
    processing_deadline: Optional[float] = None
    state: AgentState = AgentState.WAITING_FOR_INPUT
    metadata: Optional[Dict[str, Any]] = None
    is_restart: bool = False
    """True when this frame was created by RestartAgentCommand (agent restarted)."""

    @classmethod
    def type(cls) -> str:
        """Returns the type of the frame."""
        return "agent"

    def is_busy(self) -> bool:
        return self.state == AgentState.PROCESSING

    @staticmethod
    def from_dict(data: Dict[str, Any]) -> AgentStackFrame:
        """Creates a `AgentStackFrame` from a dictionary.

        Args:
            data: The dictionary to create the `AgentStackFrame` from.

        Returns:
            The created `AgentStackFrame`.
        """
        # Backward compat: old trackers may have restart frames without is_restart key
        is_restart = data.get("is_restart")
        if is_restart is None:
            is_restart = (data.get("frame_id") or "").startswith("restart_agent_")
        require_keys(
            data,
            "frame_id",
            "flow_id",
            "step_id",
            "agent_id",
            "state",
            context="Agent stack frame",
        )
        return AgentStackFrame(
            frame_id=data["frame_id"],
            flow_id=data["flow_id"],
            step_id=data["step_id"],
            agent_id=data["agent_id"],
            agent_task_id=data.get("agent_task_id", ""),
            context_id=data.get("context_id", ""),
            processing_deadline=data.get("processing_deadline"),
            state=AgentState.from_str(data["state"]),
            metadata=data.get("metadata"),
            is_restart=bool(is_restart),
        )
